case 'dashboard':if($user['role']==='STUDENT'){$requests=ai_rows($p,'SELECT r.*,c.label FROM clearance_requests r JOIN clearance_cycles c ON c.id=r.cycle_id WHERE student_user_id=? ORDER BY r.id DESC',[$user['id']]);foreach($requests as $r){echo '<section><h2>'.h($r['label']).' — '.h($r['status']).'</h2><p>Control number: <strong>'.h($r['control_number']).'</strong> · TSh '.h($r['entry_amount']).'</p><p>Generated: '.h($r['control_generated_at']?date('l, d F Y H:i:s',strtotime($r['control_generated_at'])):'—').' EAT</p><p>Payment: '.h($r['entry_status']).'</p>';if($r['rejection_reason']){echo '<p>'.h($r['rejection_reason']).'</p>';}if((!$r['started_at']||$r['legacy_request_id'])&&$r['entry_status']!=='APPROVED'&&$r['entry_status']!=='LEGACY_EXEMPT'){form_start('receipt',true);hidden('request_id',$r['id']);field('receipt','Payment receipt (PDF/JPG/PNG, up to 5 MB)','file');button('Submit receipt');}if(!$r['started_at']&&$r['entry_status']==='APPROVED'){form_start('start');hidden('request_id',$r['id']);button('Start clearance');}$stages=ai_rows($p,'SELECT s.*,u.full_name officer FROM clearance_stages s LEFT JOIN users u ON u.id=s.assigned_officer_id WHERE request_id=? ORDER BY step_number',[$r['id']]);table($stages,['step_number'=>'Step','title'=>'Office','officer'=>'Reviewer','status'=>'Status','review_cycle'=>'Cycle']);require __DIR__.'/views/student-history.php';foreach($stages as $s){if($s['status']==='REJECTED'){echo '<details open><summary>'.h($s['title']).' — correction required</summary><p>'.h($s['comments']).'</p><p>'.h($s['corrective_instructions']).'</p>';form_start('resubmit',true);hidden('stage_id',$s['id']);hidden('version',$s['row_version']);field('response','Your response');$dt=json_decode($s['details_json']??'{}',true);if((int)$s['step_number']===11&&isset($dt['control_number'])){field('control_number','Finance control number','text',$dt['control_number']);}echo '<label>Evidence (up to five files)<input type="file" name="evidence[]" multiple accept=".pdf,.png,.jpg,.jpeg"></label>';button('Submit correction');echo '</details>';}}echo '</section>';}}else{$metrics=ai_rows($p,'SELECT status,COUNT(*) total FROM clearance_requests WHERE started_at IS NOT NULL GROUP BY status');table($metrics,['status'=>'Clearance status','total'=>'Requests']);echo '<p>Use the navigation to review requests and manage your responsibilities.</p>';}break;
