case 'reviews':$rows=ai_rows($p,"SELECT s.*,u.full_name,r.status request_status FROM clearance_stages s JOIN clearance_requests r ON r.id=s.request_id JOIN users u ON u.id=r.student_user_id WHERE s.row_kind='INSTANCE' AND s.assigned_officer_id=? ORDER BY s.request_id DESC,s.step_number",[$user['id']]);foreach($rows as $s){echo '<section><h2>'.h($s['full_name']).' — '.h($s['title']).'</h2><p>'.h($s['status']).' · Review cycle '.(int)$s['review_cycle'].'</p>';$history=ai_rows($p,"SELECT e.event_type,e.reason,e.created_at FROM activity_log e WHERE e.stage_id=? AND e.family IN ('STAGE_DECISION','REVIEW_CYCLE') ORDER BY e.id",[$s['id']]);echo '<details><summary>Review history</summary>';table($history,['event_type'=>'Event','reason'=>'Comments / response','created_at'=>'Date']);foreach(ai_rows($p,'SELECT id,original_name FROM documents WHERE stage_id=? ORDER BY id',[$s['id']]) as $doc){echo '<p><a href="?page=file&id='.(int)$doc['id'].'">'.h($doc['original_name']).'</a></p>';}echo '</details>';if(in_array($s['status'],['PENDING','IN_REVIEW'],true)){form_start('review');hidden('stage_id',$s['id']);hidden('version',$s['row_version']);$dt=json_decode($s['details_json']??'{}',true);if((int)$s['step_number']===11){select_field('review_action','Decision',['APPROVE_NO_DEBT'=>'Approve: no other debt','REQUEST_PAYMENT'=>'Request additional payment','APPROVE'=>'Approve current Finance receipt','REJECT'=>'Return for correction']);field('control_number','Additional payment control number','text',$dt['control_number']??'',false);}else{select_field('review_action','Review action',['APPROVE'=>'Approve','REJECT'=>'Reject','ACCEPT_CORRECTION'=>'Approve correction and continue']);foreach(review_fields((int)$s['step_number']) as [$key,$label,$type]){if($type==='number'){field($key,$label,'number',$dt[$key]??'0');}elseif($type==='asset'){select_field($key,$label,['AVAILABLE'=>'Available','MISSING'=>'Missing'],$dt[$key]??'AVAILABLE');}else{select_field($key,$label,['CLEARED'=>'Cleared','NOT_