);form_start('membership');field('user_id','Officer ID','number');select_field('office_id','Add office membership',array_column(ai_rows($p,"SELECT id,name FROM organisation_units WHERE kind='OFFICE' AND active=1"),'name','id'));button('Add membership');break;
